function ndqInfo(k) { if (NDQ_B[k]) return NDQ_B[k]; const id = String(k).slice(2), c = CATS.find(x => x.id === id); if (!c) return null; const o = tileOv(id); return [o.ic || c.ic, o.name || SHORT[id] || c.name, (c.color || '#64748b') + '30']; }
