const dbBalTxt = d => d.bal > 0 ? `<b style="color:#b45309">পাব ${tk(d.bal)}</b>` : d.bal < 0 ? `<b style="color:#7e22ce">দেব ${tk(-d.bal)}</b>` : '<b style="color:#15803d">✅ মিটে গেছে</b>';
