  g.fillStyle = '#fde047'; g.fillRect(P, y, W - 2 * P, rowH); txt('মোট', P + 12, y + 32, F(800, 23), '#000'); mem.forEach((x, k) => txt(nm2(x.meals), P + 130 + k * colW + colW / 2, y + 32, F(800, 23), '#000', 'center')); y += rowH + 40;
  // বাজার
