  row('ভাড়াটিয়া', t.name); if (t.unit) row('ফ্ল্যাট / তলা', t.unit); row('মাস', p.m === 'adv' ? 'অগ্রিম' : lmName(p.m)); row('পরিশোধ', p.meth || 'নগদ');
