  let due = 0, got = 0, rest = 0; const cards = d.t.map(t => { const s = rtStat(t, ym), L = rtLedger(t, cur), mo = rtMonthly(t); if (s.st !== 'f') { due += mo; got += s.paid; rest += s.short; } return {t, s, L, mo}; });
