const VIS_SEC = [['hero', '💳', 'ব্যালেন্স কার্ড'], ['glance', '⚡', 'এক নজরে'], ['upd', '🔔', 'নতুন আপডেট'], ['tip', '💡', 'আজকের টিপস'], ['cards', '📂', 'সব বিভাগ (রঙিন কার্ড)']];
