(function () {
  window.__lastTouch = 0;
  ['touchstart', 'pointerdown', 'scroll', 'keydown'].forEach(ev => document.addEventListener(ev, () => { window.__lastTouch = Date.now(); }, {passive: true, capture: true}));
})();
const acSig = a => (a || []).map(r => r.id + '|' + (r.title || '').length + '|' + (r.body || '').length + '|' + (r.img ? r.img.length : 0) + '|' + (r.pub ? 1 : 0) + '|' + (r.pin ? 1 : 0) + '|' + (r.exp || '')).join(',');
const acIdle = (ms) => new Promise(r => { try { window.requestIdleCallback ? window.requestIdleCallback(() => r(), {timeout: ms || 2500}) : setTimeout(r, 300); } catch (e) { setTimeout(r, 300); } });
