    const flat = d => { const div = document.createElement('div'); div.className = 'cx lbsec'; const h = document.createElement('div'); h.className = 'lbh'; h.textContent = tx(d); div.appendChild(h); [...d.childNodes].forEach(n => { if (n.nodeName !== 'SUMMARY') div.appendChild(n); }); d.replaceWith(div); return div; };
