  if ((m = s.match(/^(\d{1,2})[\/.-](\d{1,2})(?:[\/.-](\d{2,4}))?$/))) return (m[3] ? (m[3].length === 2 ? '20' + m[3] : m[3]) : y) + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
