    for (let i = 1; i <= nd; i++) { const iso = m + '-' + String(i).padStart(2, '0'), s = ofShift(d, iso); if (sc[s] != null) sc[s]++; const k = d.marks[iso] && d.marks[iso].m; if (k) mk[k]++; }
