  const bwl = n => { if (!S.bowls[n]) { S.bowls[n] = {b: 0, r: 0, w: 0, m: 0, wd: 0, nb: 0}; S.bord.push(n); } return S.bowls[n]; };
  const fld = (n, k) => { if (!n) return; S.field[n] = S.field[n] || {c: 0, ro: 0, st: 0}; S.field[n][k]++; };
  S.c = [I.op.s, I.op.n]; S.s = 0; bat(I.op.s); bat(I.op.n); S.bowler = I.op.bw; bwl(I.op.bw); S.last = null;
