    body = `<select class="inp" onchange="CRV.tf=this.value;crHome()"><option value="">সব টুর্নামেন্ট মিলিয়ে</option>${d.tours.map(t => `<option value="${t.id}" ${tf === t.id ? 'selected' : ''}>${esc(t.name)}</option>`).join('')}</select><div>সাজান: ${[['r', 'রান'], ['w', 'উইকেট'], ['m', 'ম্যাচ']].map(a => `<span class="crp ${so === a[0] ? 'on' : ''}" onclick="CRV.so='${a[0]}';crHome()">${a[1]}</span>`).join('')}</div>` +
      (L.length ? L.map((p, i) => `<div class="nk" onclick="crGo({v:'player',pi:${i},tf:'${tf}',pt:'b'})"><span class="crav">${crAvatar(d, p.name)}</span><div class="nkt"><b>${esc(p.name)}</b><div class="hint">ম্যাচ ${bn(p.m.size)} · রান ${bn(p.r)} · উইকেট ${bn(p.w)}</div></div></div>`).join('') : '<div class="hint" style="margin:14px 0">ম্যাচ খেললে খেলোয়াড়ের হিসাব নিজে নিজে এখানে জমবে।</div>');
