  const np = () => { cv = document.createElement('canvas'); cv.width = W; cv.height = H; g = cv.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, W, H); pages.push(cv); y = PI ? padDraw(g, W, P, PI) + 10 : 40; };
  const tx = (s, x, yy, f, c, al) => { g.font = f; g.fillStyle = c; g.textAlign = al || 'left'; g.fillText(String(s), x, yy); };
  const cx = [P + 8, 640, 740, 840, 930, 1020, W - P - 8];
  np(); tx('🏏 ' + crTitle(m), P, y + 36, F(800, 36), '#0b6b4f'); y += 56; tx(m.date + ' · ' + bn(m.ov) + ' ওভার' + (crResult(m) ? ' · ' + crResult(m) : ''), P, y + 20, F(600, 22), '#334155'); y += 44;
  m.inn.forEach((I, ii) => {
    const S = crSim(m, ii); if (y > H - 400) np();
    g.fillStyle = '#0b6b4f'; g.fillRect(P, y, W - 2 * P, 46); tx(m[I.bat].name, P + 10, y + 32, F(800, 26), '#fff'); tx(bn(S.runs) + '/' + bn(S.wk) + ' (' + crOv(S.legal) + ')', W - P - 10, y + 32, F(800, 26), '#fff', 'right'); y += 46;
    [['ব্যাটার', 'রান', 'বল', '৪', '৬', 'SR']].forEach(h => { g.fillStyle = '#e8efe9'; g.fillRect(P, y, W - 2 * P, 36); h.forEach((t, i) => tx(t, i === 0 ? cx[0] : cx[i + 1], y + 26, F(700, 19), '#14231c', i === 0 ? 'left' : 'right')); y += 36; });
    S.order.forEach((n, k) => { if (y > H - 120) np(); const b = S.bats[n]; g.fillStyle = k % 2 ? '#f6f8f6' : '#fff'; g.fillRect(P, y, W - 2 * P, 54); tx(n, cx[0], y + 24, F(700, 21), '#14231c'); tx(b.out || b.how ? b.how : 'নট আউট', cx[0], y + 46, F(500, 16), '#64748b'); [bn(b.r), bn(b.b), bn(b.f4), bn(b.f6), b.b ? bn((b.r * 100 / b.b).toFixed(1)) : '০'].forEach((t, i) => tx(t, cx[i + 2], y + 34, F(i === 0 ? 800 : 500, 21), '#14231c', 'right')); y += 54; });
    if (y > H - 120) np(); tx('অতিরিক্ত ' + bn(S.extT) + ' (ওয়াইড ' + bn(S.ext.wd) + ', নো বল ' + bn(S.ext.nb) + ', বাই ' + bn(S.ext.b) + ', লেগ বাই ' + bn(S.ext.lb) + ')', cx[0], y + 30, F(500, 19), '#334155'); y += 46;
    g.fillStyle = '#e8efe9'; g.fillRect(P, y, W - 2 * P, 36); ['বোলার', 'ওভার', 'মেডেন', 'রান', 'উইকেট', 'ER'].forEach((t, i) => tx(t, i === 0 ? cx[0] : cx[i + 1], y + 26, F(700, 19), '#14231c', i === 0 ? 'left' : 'right')); y += 36;
    S.bord.forEach((n, k) => { if (y > H - 120) np(); const b = S.bowls[n]; g.fillStyle = k % 2 ? '#f6f8f6' : '#fff'; g.fillRect(P, y, W - 2 * P, 44); tx(n, cx[0], y + 30, F(700, 21), '#14231c'); [crOv(b.b), bn(b.m), bn(b.r), bn(b.w), b.b ? bn((b.r * 6 / b.b).toFixed(2)) : '০'].forEach((t, i) => tx(t, cx[i + 2], y + 30, F(i === 3 ? 800 : 500, 21), '#14231c', 'right')); y += 44; });
    if (S.fow.length) { if (y > H - 120) np(); const t = 'উইকেট পতন: ' + S.fow.map(f => bn(f.n) + '-' + bn(f.r) + ' (' + f.name + ')').join(' · '); tx(t.slice(0, 120), P, y + 30, F(500, 17), '#64748b'); y += 44; }
    y += 24;
  });
  pages.forEach((c, i) => { const g2 = c.getContext('2d'); g2.font = F(500, 17); g2.fillStyle = '#6b7a72'; g2.textAlign = 'center'; g2.fillText('আমার ভাই অ্যাপ • পেজ ' + bn(i + 1) + '/' + bn(pages.length), W / 2, H - 14); });
