function spChapTest(i) { const c = spChaps()[i], pool = c.items.filter(x => x.t !== 'rule' && x.f && x.b); if (pool.length < 4) return alert('প্রশ্ন বানানোর মতো আইটেম কম।'); spNav(() => spChap(i)); spBStart(spShuf(pool).slice(0, 20), {chap: {i, name: c.name}, left: 900}); }
