const HQ_KINDS = {bal: ['💰', 'আজকের ব্যালেন্স', 'আয়-খরচ একনজরে'], mess: ['🍛', 'মেস হিসাব', 'মিল, বাজার, বাকি'], rent: ['🏠', 'বাসা ভাড়া ও বিদ্যুৎ', 'এ মাসের জমা/বাকি'], office: ['⏰', 'অফিস টাইম', 'আজ ও এ মাসের ঘণ্টা'], cricket: ['🏏', 'ক্রিকেট স্কোর', 'চলমান/শেষ ম্যাচ'], study: ['📖', 'আজকের পড়া', 'ধারাবাহিকতা ও পড়া'], logbook: ['🚘', 'লগ বুক', 'ট্রিপ ও কিলোমিটার'], remind: ['🔔', 'রিমাইন্ডার', 'জরুরি মনে করানো'], job: ['💼', 'ড্রাইভিং জব', 'দেশি ও বিদেশি চাকরি'], note: ['📝', 'আমার নোট', 'নিজে লিখে রাখুন'], quick: ['🔗', 'দ্রুত বোতাম', 'পছন্দের ৪টি কাজ']};
const HQ_COL = [['সবুজ', 'linear-gradient(135deg,#0f766e,#065f46)', '#fff'], ['নীল', 'linear-gradient(135deg,#2563eb,#1e40af)', '#fff'], ['কমলা', 'linear-gradient(135deg,#f97316,#c2410c)', '#fff'], ['বেগুনি', 'linear-gradient(135deg,#8b5cf6,#5b21b6)', '#fff'], ['লাল', 'linear-gradient(135deg,#ef4444,#991b1b)', '#fff'], ['গাঢ়', 'linear-gradient(135deg,#475569,#0f172a)', '#fff'], ['সাদা', '#ffffff', '#14231c']];
