  if (c && c.lock && !hqAdm()) return (c.list || []).map(s => Object.assign({}, s, {_lk: 1}));
  list = ((u && u.list) || (c && c.list) || HQ_SEED).map(s => Object.assign({id: hqId()}, s));
  if (c && c.list && !hqAdm()) c.list.forEach((s, i) => { if (s.lk) { list[i] = Object.assign({}, s); } });
