function scCodeShow() { const s = SCV.soc; showModal(`<h3 style="margin:0 0 6px">🔑 যোগের কোড</h3><div style="font-size:32px;font-weight:800;letter-spacing:6px;text-align:center;color:#0b6b4f;background:#ecfdf5;border-radius:12px;padding:12px;margin:8px 0">${esc(SCV.sid)}</div><div class="hint">অ্যাপে ▸ সমিতি ▸ "কোড দিয়ে যোগ দিন" এ এই কোড দিলে অনুরোধ আসবে। ${scIsAdm() ? 'অ্যাডমিন অনুমোদন দিলে সদস্য হবে।' : ''}</div>${spBtn('📤 কোড পাঠান', `sendMsg('', 'আমার ভাই অ্যাপে "${esc(s.name)}" সমিতিতে যোগ দিতে কোড: ${SCV.sid}\\n(সমিতি ▸ কোড দিয়ে যোগ দিন)', '')`, '#16a34a')}${spBtn('বন্ধ', 'closeModal()', '#64748b')}`); }
