function scLocked(loans, uid) { let t = 0; (loans || []).forEach(l => { const k = (l.lk || {})[uid]; if (!k || ['rej', 'done'].includes(l.st)) return; if (l.uid !== uid && (l.gv || {})[uid] !== 'ok') return; t += l.st === 'run' ? Math.round(k * Math.max(0, l.amt - (l.paidP || 0)) / l.amt) : k; }); return t; }
