function scLoanVals() { const g = i => (document.getElementById(i) || {}).value || '', gs = [g('ln_g1'), g('ln_g2')].filter(Boolean).filter((x, i, a) => a.indexOf(x) === i); return {amt: +g('ln_a'), months: +g('ln_m') || 1, gs}; }
