  if (v.type === 'cycle') return (v.steps || []).map(s => bn(s.n) + ' দিন ' + (s.v ? mzQ(s.v, m) : 'ছুটি')).join(' → ') + ' (বারবার) · ' + (v.so || []).map((b, i) => b ? MZ_SL[i][1] : '').filter(Boolean).join('+');
