function mzTime() { const d = mzLoad(); [0, 1, 2].forEach(si => { const v = (document.getElementById('mz_t' + si) || {}).value; if (v) d.t[mzTk(si)] = v; }); mzSave(d); mzNotify(); toast_('✅ সময় বদলেছে'); }
function mzMark(d, iso, id, si, val) {
  const m = d.list.find(x => x.id === id); if (!m) return; d.log[iso] = d.log[iso] || {}; const k = id + '_' + si, old = d.log[iso][k] || 0, dose = mzDose(m, iso)[si] || 0, hasS = m.stock != null && m.stock !== '';
  if (old === 1 && hasS) m.stock = +m.stock + dose; if (val === 1 && hasS) m.stock = Math.max(0, +m.stock - dose); if (val) d.log[iso][k] = val; else delete d.log[iso][k];
}
function mzTake(id, si, iso, back) { const d = mzLoad(), t = iso || todayISO(), cur = mzS(d, t, id, si); mzMark(d, t, id, si, cur ? 0 : 1); mzSave(d); mzNotify(); if (back) mzDayPg(t); else mzPage(); }
function mzTakeAll(si) { const d = mzLoad(), t = todayISO(); mzDay(d, t).forEach(x => { if (x.ds[si] > 0 && !mzS(d, t, x.m.id, si)) mzMark(d, t, x.m.id, si, 1); }); mzSave(d); mzNotify(); mzPage(); toast_('✅ খেয়েছেন'); }
function mzSkipAll(si) { const d = mzLoad(), t = todayISO(); mzDay(d, t).forEach(x => { if (x.ds[si] > 0 && !mzS(d, t, x.m.id, si)) mzMark(d, t, x.m.id, si, 2); }); mzSave(d); mzNotify(); mzPage(); }
// ---------- ওষুধের পাতা (বদলানো/মোছা/ইতিহাস) ----------
function mzMed(id) {
  const d = mzLoad(), m = d.list.find(x => x.id === id); if (!m) return mzPage(); push(() => mzPage()); const t = todayISO(), cur = mzVer(m, t) || m.vs[m.vs.length - 1], l = mzLeft(m, d), stp = mzStopped(m);
  render(pageHead('💊 ' + esc(m.n)) + mzCss + `<div class="pad"><div class="cx"><b style="font-size:17px">${esc(m.n)}</b>${m.why ? `<div class="hint">${esc(m.why)}</div>` : ''}<div class="mz-r"><span>এখনকার নিয়ম</span><b style="text-align:right">${esc(mzDesc(cur, m))}</b></div><div class="mz-r"><span>খাবার</span><b>${MZ_MEAL[m.meal] || 'যেকোনো সময়'}</b></div>${m.stock != null && m.stock !== '' ? `<div class="mz-r"><span>হাতে আছে</span><b>${mzN(m.stock)}${esc(m.u)}${l != null && l < 999 ? ' · ' + bn(l) + ' দিন' : ''}</b></div>` : ''}${m.doc ? `<div class="mz-r"><span>ডাক্তার/নোট</span><b>${esc(m.doc)}</b></div>` : ''}${m.chk ? `<div class="mz-r"><span>পরের চেকআপ/টেস্ট</span><b>${mzDt(m.chk)}</b></div>` : ''}${stp ? '<div class="warn">⏸ এখন বন্ধ আছে — অ্যালার্ম আসছে না।</div>' : ''}</div>
   <button class="btn" style="width:100%;background:#7c3aed" onclick="mzForm('${id}','chg')">🔄 ডাক্তার ডোজ বদলেছেন — নতুন নিয়ম বসান</button>
   <button class="btn" style="width:100%;background:#0e7490" onclick="mzForm('${id}','edit')">✏️ তথ্য / সময়সূচি ঠিক করুন</button>
   <div style="display:flex;gap:6px"><button class="btn" style="flex:1;background:#475569" onclick="mzCal('${id}')">🗓️ ক্যালেন্ডার</button><button class="btn" style="flex:1;background:#475569" onclick="mzAddStock('${id}')">📦 স্টক যোগ</button></div>
   <div class="cx"><b>📜 ডোজ বদলের ইতিহাস</b>${m.vs.map((v, i) => `<div class="mz-r" style="align-items:flex-start"><span><b>${i ? mzDt(v.from) + ' থেকে' : (v.from ? mzDt(v.from) + ' থেকে (শুরু)' : 'শুরু')}</b>${v === cur ? ' <span class="mz-d">এখন</span>' : ''}<br><small class="hint">${esc(mzDesc(v, m))}${v.note ? '<br>📝 ' + esc(v.note) : ''}</small></span>${i ? `<span class="ed" onclick="mzVDel('${id}',${i})">🗑️</span>` : ''}</div>`).join('')}<div class="hint">নিয়ম বদলালে আগের দিনের হিসাব যেমন ছিল তেমনই থাকে।</div></div>
   ${stp ? `<button class="btn" style="width:100%;background:#16a34a" onclick="mzResume('${id}')">▶️ আবার চালু করুন</button>` : `<button class="btn" style="width:100%;background:#f59e0b" onclick="mzStop('${id}')">⏸ বন্ধ করুন (ডাক্তার বন্ধ করতে বলেছেন)</button>`}
   <button class="btn" style="width:100%;background:#b91c1c" onclick="mzDel('${id}')">🗑️ ওষুধটা মুছে ফেলুন</button><div style="height:90px"></div></div>`);
}
function mzVDel(id, i) { if (!confirm('এই নিয়মটা ইতিহাস থেকে মুছবেন? আগের নিয়ম ওই সময় থেকেও চলবে।')) return; const d = mzLoad(), m = d.list.find(x => x.id === id); m.vs.splice(i, 1); mzSave(d); mzNotify(); stack.pop(); mzMed(id); }
function mzStop(id) { if (!confirm('ওষুধ বন্ধ করবেন? আজ থেকে অ্যালার্ম আসবে না। পরে আবার চালু করা যাবে।')) return; const d = mzLoad(), m = d.list.find(x => x.id === id); m.gaps.push([todayISO(), null]); mzSave(d); mzNotify(); stack.pop(); mzMed(id); }
