  const rows = [0, 1, 2].map(si => { const it = mzDay(d, t).filter(x => x.ds[si] > 0); if (!it.length) return ''; const ok = it.every(x => mzTaken(d, t, x.m.id, si)); return `<div class="mz-r"><span>${ok ? '✅' : MZ_SL[si][0]} ${MZ_SL[si][1]} ${mzHm(d.t[mzTk(si)])}</span><span class="hint" style="text-align:right">${it.map(x => esc(x.m.n) + ' ' + mzQ(x.ds[si], x.m)).join(', ')}</span></div>`; }).join('');
