function styCol(x) { return x.c ? x.c : THM[x.id]; }
function styApply(i) {
  const x = STY[i]; if (!x) return;
  try { const bk = localStorage.getItem('stybk'); if (!bk) localStorage.setItem('stybk', JSON.stringify({thm: localStorage.getItem('thm'), dark: localStorage.getItem('dark'), tcol: localStorage.getItem('tcol'), hcard: localStorage.getItem('hcard'), hslots: localStorage.getItem('hslots')})); } catch (e) {}
  const t = thmGet(); if (x.id) { t.id = x.id; delete t.c; } else { t.id = 'custom'; t.c = Object.assign({}, x.c); } thmSet(t);
  try { localStorage.removeItem('tcol'); } catch (e) {}
  const o = hcOpt(); o.bg = x.hc; ndLS('hcard', JSON.stringify(o));
  try { const L = hqList(); L.forEach(s => { if (!s._lk) s.col = x.sl; }); hqSave(L); } catch (e) {}
  const dk = !!x.dk; document.body.classList.toggle('dark', dk); ndLS('dark', dk ? '1' : '0'); ndLS('stycur', String(i));
  applyThm(); try { applyTheme(); } catch (e) {} hgRepaint(); thmPage(); try { toast_('✅ ' + x.n + ' স্টাইল চালু'); } catch (e) {}
}
function styUndo() {
  let bk = null; try { bk = JSON.parse(localStorage.getItem('stybk') || 'null'); } catch (e) {} if (!bk) return;
  ['thm', 'dark', 'tcol', 'hcard', 'hslots'].forEach(k => { try { bk[k] == null ? localStorage.removeItem(k) : localStorage.setItem(k, bk[k]); } catch (e) {} });
  try { localStorage.removeItem('stybk'); localStorage.removeItem('stycur'); } catch (e) {}
  document.body.classList.toggle('dark', localStorage.getItem('dark') === '1'); applyThm(); try { applyTheme(); } catch (e) {} hgRepaint(); thmPage(); try { toast_('↩️ আগের সাজ ফিরেছে'); } catch (e) {}
}
function styHtml() {
  const cur = +(localStorage.getItem('stycur') || -1);
  return `<div class="cx" style="border-left:6px solid #f59e0b"><b>✨ রেডি স্টাইল</b><div class="hint">একটায় চাপলেই পুরো অ্যাপ (রং, কার্ড, ঘর, মেনু) সুন্দর একটা সাজে চলে আসবে।</div>
   <div class="sty-g">${STY.map((x, i) => { const v = styCol(x); return `<div class="sty${cur === i ? ' on' : ''}" onclick="styApply(${i})"><div class="sty-p" style="background:${v.pg || '#fff'}"><i style="background:linear-gradient(135deg,${v.p},${v.nv})"></i><i style="background:${v.ac};width:22px;flex:none"></i></div><b>${x.ic} ${esc(x.n)}</b></div>`; }).join('')}</div>
   ${localStorage.getItem('stybk') ? '<button class="btn sm" style="background:#64748b" onclick="styUndo()">↩️ স্টাইল নেওয়ার আগের সাজে ফিরুন</button>' : ''}</div>`;
}
// =====================================================================
//  p72: আইকন সাজানো ঠিক (লুকানো/দেখানো ফিরে আসে, সরাসরি 🗑️ মোছা) + 🎨 ডিজাইন ও মেনুতে অনেক ডিজাইন
// =====================================================================
async function layTilesSave(t, withLay) {
  const m = await sme(); if (!m) return false; const cfg = {tiles: t};
  if (withLay) cfg.layout = _lay.filter(g => g.name || g.ids.length).map(g => ({name: g.name || 'গ্রুপ', ids: g.ids}));
  try {
    await m.f.F.setDoc(m.f.F.doc(m.f.db, 'content', 'appconfig'), {type: 'config', title: 'config', pub: true, by: m.u.uid, cfg, createdAt: m.f.F.serverTimestamp()}, {merge: true});
    let c = ADMIN_CONTENT.find(x => x.type === 'config'); if (c) { c.cfg = Object.assign({}, c.cfg || {}, cfg); }
    try { await refreshContent(); } catch (e) {}
    c = ADMIN_CONTENT.find(x => x.type === 'config'); if (c) { c.cfg = Object.assign({}, c.cfg || {}, cfg); }
    return true;
  } catch (e) { console.error(e); return false; }
}
async function layHide(id) {
  layCommit(); const t = JSON.parse(JSON.stringify(APPCFG().tiles || {})); t[id] = t[id] || {}; t[id].hide = !t[id].hide;
  const ok = await layTilesSave(t); layRefresh(); try { adMsg(ok ? (t[id].hide ? '🙈 লুকানো হয়েছে।' : '👁️ আবার দেখা যাবে।') : '⚠️ হয়নি।'); } catch (e) {}
}
async function layDel(id) {
  if (!confirm('"' + keyName(id) + '" আইকনটা পুরোপুরি সরিয়ে দেবেন? (নিচের "মোছা আইকন" থেকে ফেরত আনা যাবে)')) return;
  layCommit(); _lay.forEach(g => { g.ids = g.ids.filter(x => x !== id); });
  const t = JSON.parse(JSON.stringify(APPCFG().tiles || {})); t[id] = Object.assign(t[id] || {}, {hide: true, del: true});
  const ok = await layTilesSave(t, true); layRefresh(); try { adMsg(ok ? '🗑️ সরানো হয়েছে।' : '⚠️ হয়নি।'); } catch (e) {}
}
async function layRestore(id) {
  layCommit(); if (!_lay.length) _lay.push({name: 'আইকন', ids: []}); if (!_lay.some(g => g.ids.includes(id))) _lay[0].ids.unshift(id);
  const t = JSON.parse(JSON.stringify(APPCFG().tiles || {})); t[id] = Object.assign(t[id] || {}, {hide: false, del: false});
  const ok = await layTilesSave(t, true); layRefresh(); try { adMsg(ok ? '↩️ ফেরত এসেছে (সবার উপরের গ্রুপে)।' : '⚠️ হয়নি।'); } catch (e) {}
}
function layDelList() {
  const t = APPCFG().tiles || {}, ids = Object.keys(t).filter(k => t[k] && t[k].del); if (!ids.length) return '';
  return `<div class="cx"><b>🗑️ মোছা আইকন</b>${ids.map(id => `<div class="layrow"><span class="lan">${esc(keyName(id))}</span><button style="background:#16a34a" onclick="layRestore('${esc(id)}')">↩️ ফেরত আনুন</button></div>`).join('')}</div>`;
}
