  if (d.nav === 1) r.push('#ndnav{left:0!important;right:0!important;bottom:0!important;width:100%!important;max-width:none!important;border-radius:0!important;transform:none!important}body.nd #app{padding-bottom:120px!important}');
  if (d.hd === 1) r.push('.ndh{border-radius:0!important}');
  if (d.bd === 1) r.push('.cx{border-left:0!important}');
  if (d.ic === 1) r.push('.hgc .hi{font-size:42px!important}'); if (d.ic === 2) r.push('.hgc .hi{font-size:22px!important}');
  if (d.fs === 1) r.push('.hgc b{font-size:17px!important}.tile b,.arm-sw span{font-size:16px!important}'); 
  if (d.gp === 1) r.push('.hg{gap:6px!important}'); if (d.gp === 2) r.push('.hg{gap:20px!important}');
  let st = document.getElementById('p72ds'); if (!st) { st = document.createElement('style'); st.id = 'p72ds'; document.head.appendChild(st); } st.textContent = r.join('\n');
