function dsgFlat() { document.querySelectorAll('#app .hgc').forEach(e => { const m = /(rgb\([^)]*\)|#[0-9a-fA-F]{3,8})/.exec(e.getAttribute('style') || ''); if (m) e.style.background = m[1]; }); }
function dsgSet(k, v) { const d = dsgGet(); d[k] = v; ndLS('dsg', JSON.stringify(d)); dsgCss(); try { hgRepaint(); } catch (e) {} ndLayout(); }
