  const o75 = window.open_; window.open_ = function (id) { const k = curHg(); window.__from = window.__pg || ''; window.__to = id; const r = o75.apply(this, arguments); try { window.__pg = id; window.__pgRn = window.__rn; window.__from = ''; window.__to = ''; if (k && !curHg() && stack.length > 0) stack[stack.length - 1] = () => window.hgOpen(k); } catch (e) {} return r; };
