  fld: [['c', 'ক্যাচ', p => p.c, p => bn(p.c) + 'টি', p => p.c > 0, 1], ['ro', 'রান আউট', p => p.ro, p => bn(p.ro) + 'টি', p => p.ro > 0, 1], ['st', 'স্টাম্পিং', p => p.st, p => bn(p.st) + 'টি', p => p.st > 0, 1], ['tot', 'মোট আউট', p => p.c + p.ro + p.st, p => bn(p.c + p.ro + p.st) + 'টি', p => p.c + p.ro + p.st > 0, 1]]
