function crTableHtml(d, t, g, q) {
  const L = crTable2(d, t, g), done = crLeagueLeft(d, t) === 0 && d.ms.some(m => m.tour === t.id && !m.ko), qn = g ? (t.qg || 2) : crQN(t);
  return `<table class="crt"><tr><th>দল</th><th>খে</th><th>জ</th><th>হা</th><th>পয়েন্ট</th><th>NRR</th></tr>${L.map((r, i) => { const inn = qn && i < qn, col = !qn ? '' : inn ? '#16a34a' : done ? '#dc2626' : '#f59e0b'; return `<tr><td>${qn ? `<span style="color:${col}">●</span> ` : ''}${esc(r.name)}</td><td>${bn(r.pl)}</td><td>${bn(r.w)}</td><td>${bn(r.l)}</td><td><b>${bn(r.p)}</b></td><td>${crNrr(r.nrr)}</td></tr>`; }).join('')}</table>${qn ? `<div class="hint">● সবুজ = শেষ ${bn(g ? qn : crQN(t))}-এ উঠছে${done ? ' · লাল = বাদ' : ' · হলুদ = লড়াইয়ে'}</div>` : ''}`;
}
function crTeamPage(d, t) {
  const gs = crGroups(t), recs = []; let hi = null, lo = null, bw = null;
  d.ms.filter(m => m.tour === t.id && m.st === 'done').forEach(m => { m.inn.forEach((I, ii) => { const S = crSim(m, ii), nm = m[I.bat].name; if (!hi || S.runs > hi.r) hi = {n: nm, r: S.runs, s: bn(S.runs) + '/' + bn(S.wk)}; if (S.wk >= S.wkMax && (!lo || S.runs < lo.r)) lo = {n: nm, r: S.runs}; }); const w = crWinner(m); if (w === 'A' || w === 'B') { const a = crSim(m, 0), b = crSim(m, 1), first = m.inn[0].bat === w; if (first) { const df = a.runs - b.runs; if (!bw || df > bw.d) bw = {d: df, t: m[w].name + ' ' + bn(df) + ' রানে'}; } } });
  return (gs.length ? gs.map(g => `<div class="cx"><b>গ্রুপ ${g}</b>${crTableHtml(d, t, g)}</div>`).join('') : `<div class="cx"><b>📊 পয়েন্ট টেবিল</b> <small class="hint">(জিত ${bn(crPw(t).w)}, টাই ${bn(crPw(t).t)})</small>${crTableHtml(d, t, '')}</div>`) +
    `<div class="cx"><b>📌 দলের রেকর্ড</b>${hi ? `<div class="r2" style="display:flex;justify-content:space-between;padding:5px 0"><span>🔝 সর্বোচ্চ স্কোর</span><b>${esc(hi.n)} ${hi.s}</b></div>` : ''}${lo ? `<div class="r2" style="display:flex;justify-content:space-between;padding:5px 0"><span>🛡️ সবচেয়ে কম রানে আউট</span><b>${esc(lo.n)} ${bn(lo.r)}</b></div>` : ''}${bw ? `<div class="r2" style="display:flex;justify-content:space-between;padding:5px 0"><span>💪 সবচেয়ে বড় জয়</span><b>${esc(bw.t)}</b></div>` : ''}${t.aw && t.aw.fair ? `<div class="r2" style="display:flex;justify-content:space-between;padding:5px 0"><span>🤝 ফেয়ার প্লে</span><b>${esc(t.aw.fair)}</b></div>` : ''}${!hi ? '<div class="hint">ম্যাচ শেষ হলে আসবে</div>' : ''}</div>`;
}

