    <div style="padding:8px 0;font-size:16px">${it.a ? '<b>' + esc(it.a) + '</b>' : '<span class="hint">অপেক্ষা…</span>'} <span class="hint">বনাম</span> ${it.b ? '<b>' + esc(it.b) + '</b>' : '<span class="hint">অপেক্ষা…</span>'}</div>
