    M.rows.forEach((r, i) => { g.fillStyle = i % 2 ? 'rgba(255,255,255,.07)' : 'rgba(255,255,255,.13)'; rr(PX, y, cw, rh - 6, 14); g.fill(); if (r[r.length - 1] === true) { g.fillStyle = th[2]; rr(PX, y, 8, rh - 6, 4); g.fill(); } let cx2 = PX + 12; M.cols.forEach((c, k) => { const w = cw * c[1], tx = String(r[k]); g.fillStyle = '#fff'; g.textAlign = c[2] === 'c' ? 'center' : c[2] === 'r' ? 'right' : 'left'; const fs = k === 1 ? fit(tx, w - 12, 700, Math.min(40, rh * .5)) : Math.min(34, rh * .42); g.font = F(k === 1 || c[0] === 'পয়েন্ট' ? 700 : 400, fs); g.fillText(tx, c[2] === 'c' ? cx2 + w / 2 : c[2] === 'r' ? cx2 + w - 10 : cx2, y + (rh - 6) / 2 + fs * .34); cx2 += w; }); y += rh; });
    g.textAlign = 'left';
