  const behind = R && (L.some(m => { const r = (R.ms || []).find(x => x.id === m.id); return !r || (m.mu || 0) > (r.mu || 0); }) || (own && R.t && (R.t.th || '') !== (t.th || '')));
  if (!(force || sig !== t.pu || behind)) { t.kn = L.map(m => m.id); crRaw(d); return chg; }
  let payload;
  if (own) payload = crShPayload('t', tid);
  else payload = {k: 't', t: R.t, ms: L.map(m => { const c = JSON.parse(JSON.stringify(m)); delete c.sh; return c; })};
  payload.del = t.dl || [];
